@testset "reluctivity: boundary dual edges and dead facets" begin
    ν₀  = 1 / FITToolbox.μ₀
    Mν  = get_reluctivity(g)
    d   = diag(Mν)
    ref = zeros(3Np)
    for k in 1:g.Nw, j in 1:g.Nv, i in 1:g.Nu
        p = _mm_idx(g, i, j, k)
        j < g.Nv && k < g.Nw && (ref[p]       = ν₀ * g.dual_edges_u[i] / g.primal_facets_u[j, k])
        i < g.Nu && k < g.Nw && (ref[p + Np]  = ν₀ * g.dual_edges_v[j] / g.primal_facets_v[i, k])
        i < g.Nu && j < g.Nv && (ref[p + 2Np] = ν₀ * g.dual_edges_w[k] / g.primal_facets_w[i, j])
    end
    @test size(Mν) == (3Np, 3Np)
    @test eltype(Mν) == Float64
    @test d ≈ ref
    # exactly zero on the dead facets, and nowhere else
    @test findall(iszero, d) == _mm_dead_facets(g)
end

@testset "reluctivity: inhomogeneous μ_r matches the cell-wise reference" begin
    # non-uniform, reaching the boundary; catches μ_r/μ₀ in place of 1/(μ₀ μ_r)
    μr = _mm_field(g, 7, 13, 29)
    h  = create_domain(g.edges_u, g.edges_v, g.edges_w; units = "m")
    h.material[:, :, :, 3] .= μr
    d  = diag(get_reluctivity(h))
    @test d ≈ _mm_reluctivity_reference(h, 1 ./ (FITToolbox.μ₀ .* μr))
    @test findall(iszero, d) == _mm_dead_facets(h)

    # uniform μ_r scales every entry by 1/μ_r
    h.material[:, :, :, 3] .= 4.0
    @test get_reluctivity(h) ≈ get_reluctivity(g) ./ 4
end

